// Generated by scripts/generate_data.py from scripts/input/cities.csv
import { places } from './places-data.js';
import { countryName, countryFlag, groupByCountry, popupHtml } from './utils.js';

const map = L.map('map').setView([50, 15], 4);

L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
  attribution: '&copy; OpenStreetMap contributors',
  maxZoom: 18,
}).addTo(map);

const legendList = document.getElementById('legend-list');
let activeId = null;
const markersById = new Map();

function setActive(id) {
  if (activeId === id) return;

  if (activeId !== null) {
    markersById.get(activeId).marker._icon?.classList.remove('pin-highlight');
    legendList.querySelector(`[data-id="${activeId}"]`)?.classList.remove('active');
  }

  activeId = id;

  if (activeId !== null) {
    markersById.get(activeId).marker._icon?.classList.add('pin-highlight');
    const item = legendList.querySelector(`[data-id="${activeId}"]`);
    item?.classList.add('active');
    item?.scrollIntoView({ block: 'nearest' });
  }
}

const byCountry = groupByCountry(places);
places.forEach((p, index) => {
  const id = p.geonameid ?? index;
  markersById.set(id, { place: p });
});

const countryEntries = [...byCountry.entries()].sort((a, b) =>
  countryName(a[0]).localeCompare(countryName(b[0]))
);

for (const [code, cities] of countryEntries) {
  const countryItem = document.createElement('li');
  countryItem.className = 'country';
  countryItem.textContent = `${countryFlag(code)} ${countryName(code)}`;
  legendList.appendChild(countryItem);

  const cityList = document.createElement('ul');
  cityList.className = 'cities';

  cities
    .sort((a, b) => a.name.localeCompare(b.name))
    .forEach(({ id, name, type }) => {
      const cityItem = document.createElement('li');
      const icon = type === 'place' ? '🏛️' : '🏙️';
      cityItem.textContent = `${icon} ${name}`;
      cityItem.dataset.id = id;
      cityItem.dataset.type = type ?? 'city';
      cityItem.addEventListener('mouseenter', () => setActive(id));
      cityItem.addEventListener('mouseleave', () => setActive(null));
      cityList.appendChild(cityItem);
    });

  legendList.appendChild(cityList);
}

places.forEach((p, index) => {
  const id = p.geonameid ?? index;
  const marker = L.marker([p.lat, p.lng])
    .addTo(map)
    .bindPopup(popupHtml(p), { autoClose: false, closeOnClick: false })
    .bindTooltip(`${p.name}, ${countryName(p.country)}`, { direction: 'top', offset: [0, -32] });

  marker.on('mouseover', () => { setActive(id); marker.openPopup(); });
  marker.on('mouseout', () => { setActive(null); marker.closePopup(); });

  markersById.get(id).marker = marker;
});

const showPlacesToggle = document.getElementById('show-places');
showPlacesToggle.addEventListener('change', () => {
  const show = showPlacesToggle.checked;
  for (const [id, { place, marker }] of markersById) {
    if (place.type === 'place') {
      if (show) {
        marker.addTo(map);
      } else {
        marker.closePopup();
        marker.remove();
      }
    }
  }
  legendList.querySelectorAll('[data-type="place"]').forEach(el => {
    el.style.display = show ? '' : 'none';
  });
});
